    n, m = read_ints()
    edges = []
    for _ in range(m):
        u, v, c = input().split()
        edges.append((int(u) - 1, int(v) - 1, c))
    return n, m, edges

def is_multiple_edge(u, v, edges):
    return (u, v) in [(e[0], e[1]) for e in edges] or (v, u) in [(e[0], e[1]) for e in edges]

