    # Create adjacency list
    adj_list = [[] for _ in range(n)]
    for u, v, c in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Check if the graph is bipartite
    color = [-1] * n
    bipartite = True

    def dfs(node, c):
        nonlocal bipartite
        color[node] = c
        for neighbor in adj_list[node]:
            if color[neighbor] == -1:
                dfs(neighbor, 1 - c)
            elif color[neighbor] == c:
